import os,re
root='AlgebraicJacobian'
files=[]
for dp,dn,fn in os.walk(root):
    for f in fn:
        if f.endswith('.lean'): files.append(os.path.join(dp,f))
print("total .lean under AlgebraicJacobian/:",len(files))
def mod(p): return p[:-5].replace('/','.')
seen=set(); stack=['AlgebraicJacobian']
imports={}
for p in files+['AlgebraicJacobian.lean']:
    try: txt=open(p).read()
    except: continue
    imports[mod(p)]=re.findall(r'^import\s+(AlgebraicJacobian[\w.]*)',txt,re.M)
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    for x in imports.get(m,[]): stack.append(x)
allm={mod(p) for p in files}
unrooted=sorted(allm-seen)
print("rooted:",len(allm&seen),"unrooted:",len(unrooted))
for u in unrooted: print("   ",u)
over=[p for p in files if sum(1 for _ in open(p))>500]
print("over 500 lines:",len(over))
EOF

